def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me, last_opp = history[-1]

    # Recent windows
    w = 10 if n >= 10 else n
    recent_opp = opp[-w:]
    recent_me = me[-w:]
    rec_opp_d = sum(1 for a in recent_opp if a == 'D')
    rec_me_d = sum(1 for a in recent_me if a == 'D')

    # Consecutive runs at tail
    tail_opp_d = 0
    for a in reversed(opp):
        if a == 'D':
            tail_opp_d += 1
        else:
            break
    tail_me_d = 0
    for a in reversed(me):
        if a == 'D':
            tail_me_d += 1
        else:
            break

    total_opp_d = opp.count('D')
    total_me_d = me.count('D')

    # Opponent mimicry of our prior action (TFT-like detection)
    mimic = 0
    if n > 1:
        for i in range(1, n):
            if history[i][1] == history[i - 1][0]:
                mimic += 1
    mimic_rate = mimic / (n - 1) if n > 1 else 0.0

    # Endgame: exploit a bit, but not blindly
    if n >= 97:
        # Against clearly cooperative opponents, defect late.
        if total_opp_d == 0 or (total_opp_d <= 1 and tail_opp_d == 0):
            return 'D'
        # Against a retaliator, staying C keeps mutual C in last rounds if they were C
        if last_opp == 'C' and total_opp_d <= 2:
            return 'C'
        return 'D'

    # Phase 1: opening
    if n == 1:
        return 'C'
    if n == 2:
        # If they defected on our C, punish once; otherwise continue C
        if last_opp == 'D':
            return 'D'
        return 'C'
    if n == 3:
        # Repair after single punishment, but watch for sustained D
        if total_opp_d >= 2 and last_opp == 'D':
            return 'D'
        return 'C'

    # Sustained defector: protect ourselves.
    if total_opp_d >= 8 and total_opp_d * 2 >= n and rec_opp_d * 3 >= w * 2:
        # Rare probe to detect a change of heart
        if tail_opp_d >= 4 and rec_opp_d == w:
            return 'D'
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # Strong recent defection rate
    if w >= 6 and rec_opp_d * 2 >= w:
        # If we are also heavily defecting, try repairing via C after a C
        if last_opp == 'C' and rec_me_d >= 2:
            return 'C'
        return 'D'

    # Against mimic/TFT: use generous tit-for-tat.
    if mimic_rate >= 0.6 and n >= 6:
        if last_opp == 'D':
            # Single-shot punishment then forgive, unless streak is long
            if tail_opp_d >= 3:
                return 'D'
            return 'C'
        return 'C'

    # Opponent mostly cooperative
    if total_opp_d <= max(1, n // 10):
        # Rarely probe for exploitability, but be cautious right after our own D
        if last_me == 'D' and last_opp == 'C':
            return 'C'
        if n >= 20 and total_opp_d == 0 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Opponent occasionally defects: generous TFT
    if last_opp == 'D':
        # Forgive if our own defection likely triggered it
        if tail_me_d >= 1 and rec_opp_d <= 2:
            return 'C'
        # Long opponent D streak: retaliate
        if tail_opp_d >= 3:
            return 'D'
        # Otherwise punish once, then forgive
        if rng.random() < 0.35:
            return 'C'
        return 'D'
    else:
        # last_opp == 'C'
        # Exploit slightly more against moderately cooperative opponents
        if rec_opp_d == 0 and n >= 15 and rng.random() < 0.07:
            return 'D'
        if rec_me_d >= 3 and rec_opp_d <= 1:
            # We were being aggressive; return to C to avoid retaliation
            return 'C'
        return 'C'
